'use strict';
(() => {
const api=window.winterbell,root=document.getElementById('winterbell-ui'),q=s=>root.querySelector(s);
const languageView=window.createGlaciaLanguageView(root);
const state={dark:false,layout:'cards',page:'all',autoLock:5,language:'en'};let current={hasVault:false,locked:true,accounts:[]},pending=null,toastTimer,previousFocus,busy=false,refreshing=false,focusTouch=0,modalMode='';
let editingNameId=null,nameDraft='',localSetup=false,setupMode='',cloudChoices=[];
let deleteTimer=null,deleteRequest=null;
let dragAccountId=null,dropAccountId=null,dropAfter=false;
let pointerDrag=null,dragScrollFrame=0,suppressReorderClickUntil=0;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<span class="wb-icon"><i data-lucide="${name}" aria-hidden="true"></i></span>`;
const icons=()=>window.lucide?.createIcons({attrs:{width:18,height:18}});
const extras=window.createGlaciaExtras({root,api,icon,icons,safe,getStatus:()=>current,getPage:()=>state.page,setStatus,go:page=>{state.page=page;renderPage();},modal,closeModal,toast});
function toast(text){clearTimeout(toastTimer);q('#wb-toast').textContent=text;q('#wb-toast').hidden=false;toastTimer=setTimeout(()=>q('#wb-toast').hidden=true,3500);}
function theme(){root.dataset.theme=state.dark?'dark':'light';root.dataset.layout=state.layout;q('#wb-theme').setAttribute('aria-checked',String(state.dark));q('#wb-theme').dataset.on=String(state.dark);q('#wb-theme-label').textContent=state.dark?'Polar night':'Snow light';if(!q('#wb-theme-icon svg'))icons();}
async function preferences(){await api.preferences({dark:state.dark,layout:state.layout,autoLock:state.autoLock,language:state.language,animateTheme:true,reducedMotion:window.matchMedia('(prefers-reduced-motion: reduce)').matches});}
function applyLanguage(value){state.language=window.GlaciaI18n.normalizeLanguage(value);languageView.setLanguage(state.language);const select=q('#wb-language');if(select)select.value=state.language;}
api.onLanguageChanged?.(applyLanguage);
function setStatus(data){current=data;extras.renderFolders();extras.updateSync();extras.updateBackup();applyLanguage(data.preferences.language);updateWindowState(data.window);state.dark=data.preferences.dark;state.layout=data.preferences.layout;state.autoLock=data.preferences.autoLock;theme();if(data.locked){closeModal(false);showLock();}else{q('#wb-locked').hidden=true;q('#wb-unlocked').hidden=false;renderPage();}}
function updateWindowState(data){
 if(!data)return;const button=q('[data-window-action="maximize"]');button.setAttribute('aria-label',data.maximized?'Restore':'Maximize');button.title=data.maximized?'Restore':'Maximize';q('[data-window-maximize]').toggleAttribute('hidden',!!data.maximized);q('[data-window-restore]').toggleAttribute('hidden',!data.maximized);
}
root.querySelectorAll('[data-window-action]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();api.windowAction({action:button.dataset.windowAction}).then(updateWindowState).catch(err=>toast(err.message));}));
api.onWindowState?.(updateWindowState);
function privacyNotice(){return `<div class="wb-privacy-notice"><p>Google sign-in uses your email and Glacia’s private Drive app data for encrypted sync. Local-only use is optional.</p><button class="wb-public-link cursor-interaction" data-public-page="privacy">Privacy policy ${icon('external-link')}</button></div>`;}
function showLock(){extras.renderFolders();extras.updateSync();extras.updateBackup();
 q('#wb-unlocked').hidden=true;q('#wb-locked').hidden=false;q('#wb-account-grid').innerHTML='';q('#wb-tools-view').innerHTML='';root.querySelectorAll('.wb-count').forEach(el=>el.textContent='0');
 const c=current.cloud||{},first=!current.hasVault&&!localSetup;
 let body;
 if(!localSetup&&!c.connected){
  body=`<h2>Welcome to Glacia.</h2><p>Sign in with Google to back up and restore your Glacia accounts.</p><div class="wb-unlock-fields wb-google-welcome"><div class="wb-first-steps"><span>1 · Google sign-in</span><span>2 · Choose your starting point</span><span>3 · Protect your vault</span></div><button class="wb-primary cursor-interaction" data-first-google ${c.connecting||!c.configured?'disabled':''}>${icon('log-in')}${c.connecting?'Waiting for Google…':'Sign in with Google'}</button>${c.connecting?'<button class="wb-secondary cursor-interaction" data-cloud-cancel>Cancel sign-in</button>':''}${!c.configured?'<p class="wb-password-note">Google sign-in is unavailable in this build. You can continue with a local vault.</p>':''}<p class="wb-password-note">Bring Google Authenticator keys in through a one-time transfer QR import. Glacia then keeps its own encrypted cloud backup.</p><button class="wb-secondary cursor-interaction" data-local-setup>${current.hasVault?'Unlock local vault':'Continue with a local vault'}</button></div>`;
 }else if(first&&!setupMode){
  body=`<h2>Your vault, your starting point.</h2><p>Signed in as ${safe(c.email)}</p><div class="wb-unlock-fields wb-start-options"><button class="wb-start-choice cursor-interaction" data-setup-mode="local">${icon('file-up')}<span><strong>Restore a local backup</strong><small>Import a backup file, then sync it to a new cloud vault.</small></span></button><button class="wb-start-choice cursor-interaction" data-setup-mode="cloud">${icon('cloud-download')}<span><strong>Restore a Glacia cloud backup</strong><small>Bring back a vault you already synced with this Google account.</small></span></button><button class="wb-start-choice cursor-interaction" data-setup-mode="new">${icon('plus')}<span><strong>Start a new synced vault</strong><small>Start empty, then add keys or import Google Authenticator transfer QRs.</small></span></button><button class="wb-secondary cursor-interaction" data-first-disconnect>Use another Google account</button></div>`;
 }else{
  const google=first&&c.connected,restore=google&&setupMode==='cloud';
  body=`<h2>${current.hasVault?'A moment of quiet.':google?'Protect your Glacia vault.':'Welcome to Glacia.'}</h2><p>${current.hasVault?'Unlock your accounts on this PC.':google?'Signed in as '+safe(c.email):'Choose a password to protect your local authenticator vault.'}</p><div class="wb-unlock-fields">${current.rememberedLogin?'<button class="wb-primary cursor-interaction" id="wb-resume-login">Unlock on this PC</button><p class="wb-password-note">Your login is saved with Windows. You can also enter your password below.</p>':''}<label>${current.hasVault?'Vault password':'Create vault password'}<input id="wb-vault-password" type="password" autocomplete="${current.hasVault?'current-password':'new-password'}" placeholder="${current.hasVault?'Your vault password':'At least 6 characters'}" maxlength="1024"></label>${current.hasVault?'':'<label>Confirm vault password<input id="wb-vault-confirm" type="password" autocomplete="new-password" placeholder="Enter it again" maxlength="1024"></label>'}${google?`${restore?`<label>Cloud backup<select id="wb-first-cloud-vault">${cloudChoices.map(v=>`<option value="${safe(v.id)}" data-i18n-skip>${safe(v.name)}</option>`).join('')}</select></label>`:'<label>Cloud vault name<input id="wb-first-cloud-name" value="My Glacia vault" maxlength="80"></label>'}<label>${restore?'Existing sync password':'Create sync password'}<input id="wb-first-sync-password" type="password" autocomplete="off" maxlength="1024" placeholder="At least 12 characters"></label><label>Confirm sync password<input id="wb-first-sync-confirm" type="password" autocomplete="off" maxlength="1024" placeholder="Enter it again"></label><p class="wb-remember-note">${restore?'Use the same sync password you set on your other Glacia computer.':'Your new cloud vault starts separately from any older backups.'} Your local vault password can be different.</p>`:''}<label class="wb-remember-login"><input id="wb-remember-login" type="checkbox" ${current.rememberedLogin?'checked':''}><span>Keep me logged in on this PC</span></label><p class="wb-remember-note">Windows protects your saved login. Lock requires your vault password; Sign Out also signs out of Google.</p><button class="wb-primary cursor-interaction" id="${google?'wb-onboard-create':'wb-unlock-real'}">${icon(current.hasVault?'key-round':'shield-check')}${current.hasVault?'Unlock Glacia':restore?'Create vault & restore accounts':google&&setupMode==='local'?'Create vault & choose backup':google?'Create my synced vault':'Create my vault'}</button><p class="wb-password-note">Keep your passwords somewhere safe. Google sign-in cannot recover your sync password.</p>${google?'<button class="wb-secondary cursor-interaction" data-setup-back>Back to choices</button>':current.hasVault?c.connected?'<p class="wb-password-note">Signed in with Google: '+safe(c.email)+'</p>':`<button class="wb-secondary cursor-interaction" data-first-google ${c.configured?'':'disabled'}>Sign in with Google</button>`:'<button class="wb-secondary cursor-interaction" data-back-to-welcome>Back to Google sign-in</button>'}</div>`;
 }
 q('#wb-locked').innerHTML=`<div class="wb-logo"><span class="wb-brand-mark" aria-hidden="true"></span></div>${body}${privacyNotice()}<div class="wb-form-error" id="wb-unlock-error" role="alert" ${c.error||current.loginNotice?'':'hidden'}>${safe(c.error||current.loginNotice||'')}</div>`;
 icons();root.querySelectorAll('[data-page],#wb-add-nav,#wb-lock-button,#wb-lock-short').forEach(b=>b.disabled=true);q('#wb-lock-button').disabled=!c.connected;
}
function enabled(){root.querySelectorAll('[data-page],#wb-add-nav,#wb-lock-button,#wb-lock-short').forEach(b=>b.disabled=false);}
function format(code){const point=code.length/2;return code.slice(0,point)+' '+code.slice(point);}
function filtered(){const term=q('#wb-search').value.toLowerCase();return current.accounts.filter(a=>(state.page==='all'||(state.page==='favorites'?a.favorite:a.folder===state.page))&&`${a.name} ${a.email}`.toLowerCase().includes(term));}
function clearAccountDrag(){if(pointerDrag&&root.hasPointerCapture(pointerDrag.pointerId))root.releasePointerCapture(pointerDrag.pointerId);pointerDrag=null;cancelAnimationFrame(dragScrollFrame);q('.wb-drag-preview')?.remove();dragAccountId=null;dropAccountId=null;dropAfter=false;root.querySelectorAll('.is-dragging,.is-drop-before,.is-drop-after').forEach(el=>el.classList.remove('is-dragging','is-drop-before','is-drop-after'));q('#wb-account-grid').classList.remove('wb-reorder-vertical');}
async function placeAccount(id,targetId,after){
 if(busy||current.locked)return;busy=true;
 try{const data=await api.reorderAccounts({id,targetId,after});clearAccountDrag();setStatus(data);q('[data-reorder="'+id+'"]')?.focus();if(!data.locked)toast('Account order saved.');}
 catch(err){clearAccountDrag();error(err.message);}finally{busy=false;}
}
function renderAccounts(){extras.renderFolders();const shown=filtered();q('#wb-account-grid').innerHTML=shown.length?shown.map(a=>`<article class="wb-account" data-account-id="${a.id}"><div class="wb-account-top"><button class="wb-reorder cursor-interaction" data-reorder="${a.id}" aria-label="Reorder ${safe(a.name)}" title="Drag to reorder. Alt + Up or Down to move.">${icon('grip-vertical')}</button><div class="wb-service-mark" aria-hidden="true">${extras.serviceMark(a)}</div><div class="wb-service-text"><h3>${editingNameId===a.id?`<input class="wb-name-input" data-name-input="${a.id}" aria-label="Account name" value="${safe(nameDraft)}" maxlength="120" required autocomplete="off">`:`<span data-i18n-skip>${safe(a.name)}</span>`}</h3><p class="wb-account-email">${safe(a.email)}</p></div><div class="wb-account-header-actions"><button class="wb-edit-name cursor-interaction" data-rename="${a.id}" aria-label="${editingNameId===a.id?'Save name for':'Edit name for'} ${safe(a.name)}" title="${editingNameId===a.id?'Save name':'Edit name'}">${icon(editingNameId===a.id?'check':'pencil')}</button><button class="wb-favorite cursor-interaction" data-favorite="${a.id}" aria-pressed="${a.favorite}" aria-label="Favorite ${safe(a.name)}">${icon('star')}</button><button class="wb-delete cursor-interaction" data-delete="${a.id}" aria-label="Delete ${safe(a.name)}" title="Delete authenticator">${icon('trash-2')}</button></div></div><div class="wb-code-row"><span class="wb-code${a.remaining<=5?' is-expiring':''}" data-code="${a.id}">${format(a.code)}</span><div class="wb-code-actions"><button class="wb-icon-button cursor-interaction" data-qr="${a.id}" aria-label="Send ${safe(a.name)} to phone">${icon('qr-code')}</button><button class="wb-icon-button cursor-interaction" data-copy="${a.id}" aria-label="Copy code for ${safe(a.name)}">${icon('copy')}</button></div></div><div class="wb-track" aria-hidden="true"><div class="wb-track-fill" data-track="${a.id}" style="width:${a.remaining/a.period*100}%"></div></div><div class="wb-account-bottom"><select class="wb-folder-tag wb-folder-select ${a.folder==='work'?'work':''}" data-account-folder="${a.id}" data-folder-color="${extras.folderColor(a.folder)}" aria-label="Folder for ${safe(a.name)}">${extras.folderOptions(a.folder)}</select><span class="wb-code-kind" data-remaining="${a.id}">${a.remaining}s · ${a.period} SEC</span></div></article>`).join(''):`<div class="wb-empty"><strong>${current.accounts.length?'No matching accounts.':'Your winter starts here.'}</strong><p>${current.accounts.length?'Try a different search or folder.':'Add an authenticator or import your accounts.'}</p><button class="wb-secondary cursor-interaction" data-open-add>${icon('plus')}Add authenticator</button></div>`;q('#wb-all-count').textContent=current.accounts.length;q('#wb-fav-count').textContent=current.accounts.filter(a=>a.favorite).length;q('#wb-personal-count').textContent=current.accounts.filter(a=>a.folder==='personal').length;q('#wb-work-count').textContent=current.accounts.filter(a=>a.folder==='work').length;icons();}
function renderPage(){if(current.locked)return;enabled();extras.renderFolders();const customFolder=extras.folders().find(folder=>folder.id===state.page&&folder.id.startsWith('folder-'));if(state.page.startsWith('folder-')&&!customFolder)state.page='all';const meta=customFolder?[customFolder.name,'Your accounts, organized your way.',customFolder.name]:{all:['Your accounts','Everything you need for your next sign-in.','Accounts'],favorites:['Your favorites','The accounts you reach for most.','Favorites'],personal:['Personal accounts','A little space for your everyday world.','Personal'],work:['Work accounts','Keep your working world together.','Work'],backup:['Import & export','Bring your accounts home. Take a backup with you.','Import / Export'],cloud:['Google sync','Your winter, wherever you sign in.','Google sync'],help:['Help & Recovery','A little guidance for your Glacia journey.','Help & Recovery'],settings:['Make it yours','Small details. Your kind of calm.','Settings']}[state.page];q('#wb-heading').toggleAttribute('data-i18n-skip',!!customFolder);q('#wb-breadcrumb').toggleAttribute('data-i18n-skip',!!customFolder);q('#wb-heading').textContent=meta[0];q('#wb-subtitle').textContent=meta[1];q('#wb-breadcrumb').textContent=meta[2];root.querySelectorAll('[data-page]').forEach(b=>{if(b.dataset.page===state.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const tools=['backup','settings','cloud','help'].includes(state.page);q('#wb-accounts-view').hidden=tools;q('#wb-tools-view').hidden=!tools;q('#wb-add').hidden=tools;if(!tools){renderAccounts();return;}
if(state.page==='help'){extras.renderHelp();return;}if(state.page==='cloud'){renderCloud();return;}
if(state.page==='backup')q('#wb-tools-view').innerHTML=extras.backupPanel()+`<div class="wb-info-strip">${icon('shield-check')}<span>Your local vault and Glacia backup files are encrypted. Import text links, restore a backup, or send an account to your phone.</span></div><div class="wb-flow-grid"><button class="wb-flow-choice cursor-interaction" data-import-file><span class="wb-flow-symbol">${icon('file-up')}</span><strong>Import accounts</strong><p>Open your authenticator .txt file or restore a .winterbell backup.</p><span class="wb-flow-link">Choose a file ${icon('arrow-up-right')}</span></button><button class="wb-flow-choice cursor-interaction" data-export><span class="wb-flow-symbol">${icon('archive')}</span><strong>Export accounts</strong><p>Create an encrypted backup or export setup links for another authenticator.</p><span class="wb-flow-link">Choose format ${icon('arrow-up-right')}</span></button><button class="wb-flow-choice cursor-interaction" data-open-qr><span class="wb-flow-symbol">${icon('scan-line')}</span><strong>Scan a QR image</strong><p>Upload a setup QR screenshot or photo to add an authenticator.</p><span class="wb-flow-link">Choose QR image ${icon('arrow-up-right')}</span></button><button class="wb-flow-choice cursor-interaction" data-phone-picker><span class="wb-flow-symbol">${icon('smartphone')}</span><strong>Send to phone</strong><p>Create a setup QR for an account, then scan it in Google Authenticator.</p><span class="wb-flow-link">Choose an account ${icon('arrow-up-right')}</span></button></div><button class="wb-secondary cursor-interaction" data-paste-import>${icon('clipboard-paste')}Paste authenticator links</button>`;
else q('#wb-tools-view').innerHTML=`<section class="wb-page"><h2>Your own little winter.</h2><div class="wb-setting-row"><div><strong>Language</strong><p>Changes immediately. No restart needed.</p></div><select id="wb-language" aria-label="Language"><option data-i18n-skip value="en" ${state.language==='en'?'selected':''}>English</option><option data-i18n-skip value="id" ${state.language==='id'?'selected':''}>Bahasa Indonesia</option><option data-i18n-skip value="ja" ${state.language==='ja'?'selected':''}>日本語</option></select></div><div class="wb-setting-row"><div><strong>Appearance</strong><p>Snow light by day. Polar night after dark.</p></div><select id="wb-appearance" aria-label="Appearance"><option value="light" ${!state.dark?'selected':''}>Snow light</option><option value="dark" ${state.dark?'selected':''}>Polar night</option></select></div><div class="wb-setting-row"><div><strong>Account layout</strong><p>Roomy cards or a more compact list.</p></div><select id="wb-layout" aria-label="Account layout"><option value="cards" ${state.layout==='cards'?'selected':''}>Comfortable cards</option><option value="compact" ${state.layout==='compact'?'selected':''}>Compact list</option></select></div><div class="wb-setting-row"><div><strong>Start with Windows</strong><p id="wb-startup-note">${safe(current.startup?.message||'Open Glacia automatically when you sign in to Windows.')}</p></div><button class="wb-startup-toggle cursor-interaction" id="wb-start-with-windows" role="switch" aria-label="Start with Windows" aria-describedby="wb-startup-note" aria-checked="${!!current.startup?.enabled}" data-on="${!!current.startup?.enabled}" ${current.startup?.available?'':'disabled'}><span id="wb-startup-label">${current.startup?.enabled?'On':'Off'}</span><span class="wb-switch" aria-hidden="true"></span></button></div><div class="wb-setting-row"><div><strong>Automatic lock</strong><p>Windows lock or sleep still locks your vault.</p></div><select id="wb-auto-lock" aria-label="Automatic lock">${[1,5,15,0].map(n=>`<option value="${n}" ${state.autoLock===n?'selected':''}>${n===0?'Never':`After ${n} minute${n===1?'':'s'}`}</option>`).join('')}</select></div><div class="wb-setting-row"><div><strong>Keep me logged in</strong><p>${current.rememberedLogin?'Saved on this PC. Idle lock is paused; Windows lock still protects your vault.':'Off. Enable it when unlocking your vault.'}</p></div>${current.rememberedLogin?'<button class="wb-secondary cursor-interaction" data-forget-login>Forget saved login</button>':'<span class="wb-preview">OFF</span>'}</div><div class="wb-setting-row wb-about-row"><div class="wb-about-copy"><strong>About Glacia</strong><p class="wb-about-description"><span>Glacia Authenticator is app from Winter Garden Project for your two-step Verification Codes.</span> <span>It keeps your keys in an encrypted local vault, works offline, and supports optional encrypted Google sync across your computers.</span></p><p class="wb-about-credit">Created by <strong>Enochi Sasaina</strong>.<br>A little calm, every sign-in.</p><p class="wb-about-version">Windows desktop · version 0.4.3</p><button class="wb-public-link cursor-interaction" data-public-page="privacy">Privacy policy ${icon('external-link')}</button></div><span class="wb-preview">LOCAL VAULT</span></div></section>`;extras.updateBackup();icons();}

function renderCloud(){
 const c=current.cloud||{},status=c.connecting?'Waiting for Google sign-in':!c.connected?'Not connected':c.syncing?'Syncing your encrypted vault':c.enabled?'Automatic sync is on':'Sync paused';
 q('#wb-tools-view').innerHTML=`<section class="wb-page wb-cloud-page"><div class="wb-info-strip">${icon('shield-check')}<span>Your accounts are encrypted before uploading to Glacia’s private Google Drive app data. Keep the same sync password on every computer.</span></div><div class="wb-cloud-card"><span class="wb-flow-symbol">${icon('cloud')}</span><h2>${safe(status)}</h2><p>${c.connected?'<span data-i18n-skip>'+safe(c.email)+'</span>':'Connect your Google account to carry your accounts between Glacia computers.'}</p>${c.connected?`<p class="wb-step-note">${c.rememberedSync?'Sync resumes automatically after you unlock this vault.':'Unlock sync once to remember it securely on this PC.'}</p>`:''}${c.lastSync?'<p><span>Last synced:</span> <span data-i18n-date="'+safe(c.lastSync)+'">'+safe(new Date(c.lastSync).toLocaleString(state.language))+'</span></p>':''}${c.error?'<p class="wb-form-error" role="alert">'+safe(c.error)+'</p>':''}<div class="wb-cloud-actions">${!c.configured?'<p>Google sign-in is unavailable in this build.</p>':c.connecting?'<button class="wb-secondary cursor-interaction" data-cloud-cancel>Cancel sign-in</button>':!c.connected?'<button class="wb-primary cursor-interaction" data-cloud-signin>Sign in with Google</button>':c.enabled?'<button class="wb-primary cursor-interaction" data-cloud-now '+(c.syncing?'disabled':'')+'>Sync now</button><button class="wb-secondary cursor-interaction" data-cloud-pause>Pause sync</button>':'<button class="wb-primary cursor-interaction" data-cloud-enable>Unlock sync</button>'}${c.connected?'<button class="wb-secondary cursor-interaction" data-cloud-disconnect>Disconnect Google</button>':''}</div></div><div class="wb-setting-row"><div><strong>Encrypted on every computer</strong><p>Sync runs while Glacia is open, unlocked, and online. Locking clears the sync password from memory.</p></div></div><div class="wb-setting-row"><div><strong>Keep an independent backup</strong><p>Google sign-in alone cannot decrypt your vault. Your sync password is needed to restore it.</p></div></div><p class="wb-step-note">Google sync connects Glacia computers. Use Send to phone for Google Authenticator.</p>${privacyNotice()}</section>`;icons();
}
function cloudUnlock(){modal('Unlock your cloud vault',`<p>Choose a sync password the first time. On another computer, enter that same password to restore your accounts.</p><p class="wb-step-note">Your sync password will be remembered securely for this vault on this PC.</p><label>Sync password<input id="wb-sync-password" type="password" autocomplete="off" maxlength="1024" placeholder="At least 12 characters"></label><label>Confirm sync password<input id="wb-sync-confirm" type="password" autocomplete="off" maxlength="1024" placeholder="Enter it again"></label><div class="wb-info-strip">${icon('key-round')}<span>Your local vault password can be used here if you prefer. Google sign-in cannot recover a forgotten sync password.</span></div><button class="wb-primary cursor-interaction" data-cloud-unlock>Unlock and sync</button>`,'cloud-unlock');}

function modal(title,body,mode=''){if(current.locked)return;clearDeleteConfirmation();modalMode=mode;if(q('#wb-modal-shade').hidden)previousFocus=document.activeElement;q('#wb-modal-shade').hidden=false;q('.wb-modal').innerHTML=`<div class="wb-modal-head"><h2 id="wb-modal-title">${title}</h2><button class="wb-icon-button cursor-interaction" data-close-modal aria-label="Close dialog">${icon('x')}</button></div>${body}<div class="wb-form-error" id="wb-dialog-error" role="alert" hidden></div>`;q('.wb-shell').inert=true;icons();q('[data-close-modal]').focus();sizeModal();}
function sizeModal(){if(!q('#wb-modal-shade').hidden)root.style.minHeight=Math.max(705,q('.wb-modal').offsetHeight+120)+'px';}
new ResizeObserver(sizeModal).observe(q('.wb-modal'));
function closeModal(focus=true){clearDeleteConfirmation();q('#wb-modal-shade').hidden=true;q('.wb-modal').innerHTML='';q('.wb-shell').inert=false;root.style.minHeight='';modalMode='';pending=null;if(focus&&previousFocus?.isConnected)previousFocus.focus();}
function error(text){if(current.locked&&q('#wb-unlock-error')){q('#wb-unlock-error').textContent=text;q('#wb-unlock-error').hidden=false;return;}const el=q('#wb-dialog-error');if(el&&!q('#wb-modal-shade').hidden){el.textContent=text;el.hidden=false;sizeModal();}else toast(text);}
function clearDeleteConfirmation(){clearInterval(deleteTimer);deleteTimer=null;if(deleteRequest){deleteRequest=null;api.cancelDelete().catch(()=>{});}}
async function deleteModal(id){
 const account=current.accounts.find(a=>a.id===id);if(!account)return;
 modal('Delete authenticator?',`<p>Remove <strong data-i18n-skip>${safe(account.name)}</strong><br><span data-i18n-skip>${safe(account.email)}</span> from Glacia?</p><p>You will need its setup key or a backup to add it again. This removal will sync to your other Glacia computers when Google sync is enabled.</p><div class="wb-delete-actions"><button class="wb-secondary cursor-interaction" data-close-modal>Cancel</button><button class="wb-primary wb-danger cursor-interaction" data-delete-confirm disabled>Delete (5s)</button></div>`,'delete');q('.wb-delete-actions [data-close-modal]').focus();
 const request=await api.prepareDelete({id});if(modalMode!=='delete'||current.locked){api.cancelDelete().catch(()=>{});return;}deleteRequest={id,token:request.token,readyAt:performance.now()+request.delay};
 const update=()=>{const button=q('[data-delete-confirm]');if(!button||!deleteRequest){clearInterval(deleteTimer);return;}const remaining=Math.max(0,Math.ceil((deleteRequest.readyAt-performance.now())/1000));button.textContent=remaining?`Delete (${remaining}s)`:'Delete';button.disabled=remaining>0;if(!remaining){clearInterval(deleteTimer);deleteTimer=null;}};update();deleteTimer=setInterval(update,100);
}
function addModal(tab='manual'){modal('Add authenticator',`<p>Connect an account with its setup key, link, or QR image.</p><div class="wb-modal-tabs" role="tablist" aria-label="Add authenticator method"><button class="cursor-interaction" role="tab" aria-selected="${tab==='manual'}" data-add-tab="manual">Setup key</button><button class="cursor-interaction" role="tab" aria-selected="${tab==='link'}" data-add-tab="link">Setup link</button><button class="cursor-interaction" role="tab" aria-selected="${tab==='qr'}" data-add-tab="qr">QR image</button></div><div id="wb-add-fields">${tab==='manual'?`<div class="wb-fields"><label>Service name<input id="wb-new-service" placeholder="e.g. Google" maxlength="120" autocomplete="off"></label><label>Account label<input id="wb-new-email" placeholder="Email or username" maxlength="240" autocomplete="off"></label></div><label>Secret setup key<input id="wb-new-secret" type="password" placeholder="Enter the Base32 setup key" maxlength="2048" autocomplete="off" spellcheck="false"></label><label>Folder<select id="wb-new-folder">${extras.folderOptions('personal')}</select></label><details><summary class="cursor-interaction">Advanced settings</summary><div class="wb-fields"><label>Code digits<select id="wb-new-digits"><option>6</option><option>8</option></select></label><label>Refresh period (seconds)<input id="wb-new-period" type="number" value="30" min="1" max="3600"></label></div><label>Algorithm<select id="wb-new-algorithm"><option>SHA1</option><option>SHA256</option><option>SHA512</option></select></label></details><button class="wb-primary cursor-interaction" data-save-manual>${icon('plus')}Add authenticator</button>`:tab==='link'?`<label>Setup link<input id="wb-new-uri" type="password" placeholder="otpauth://totp/…" maxlength="8192" autocomplete="off" spellcheck="false"></label><button class="wb-primary cursor-interaction" data-save-link>${icon('plus')}Add authenticator</button>`:`<div class="wb-qr-preview">${icon('scan-line')}<h3>Scan from an image</h3><p>Choose a PNG, JPG or WebP QR image.<br>Setup and Google transfer QRs are scanned on this PC.</p><button class="wb-secondary cursor-interaction" data-upload-qr>${icon('image-up')}Upload QR image</button></div><p class="wb-step-note">For Google Authenticator: open Transfer accounts &gt; Export accounts on your phone, select your keys, then upload a clear image of each QR page. These images contain secret keys; keep them private.</p>`}</div><div class="wb-modal-foot">${icon('shield-check')}Saved in your encrypted local vault.</div>`,'add');}
function exportTabs(format){return `<div class="wb-modal-tabs" role="tablist" aria-label="Export format"><button class="cursor-interaction" role="tab" aria-selected="${format==='encrypted'}" data-export-format="encrypted">Encrypted backup</button><button class="cursor-interaction" role="tab" aria-selected="${format==='text'}" data-export-format="text">For another app (.txt)</button></div>`;}
function exportModal(){if(!current.accounts.length){toast('Add an account before exporting a backup.');return;}modal('Export your accounts.',`${exportTabs('encrypted')}<p>Export all ${current.accounts.length} accounts to an encrypted .winterbell file.</p><label>Backup password<input id="wb-export-password" type="password" autocomplete="new-password" placeholder="At least 12 characters" maxlength="1024"></label><label>Confirm backup password<input id="wb-export-confirm" type="password" autocomplete="new-password" placeholder="Enter it again" maxlength="1024"></label><div class="wb-info-strip">${icon('key-round')}<span>You’ll need this password to restore the backup on any PC.</span></div><button class="wb-primary cursor-interaction" data-save-backup>${icon('download')}Save encrypted backup</button>`,'export');}
function textExportModal(){if(!current.accounts.length){toast('Add an account before exporting.');return;}modal('Export your accounts.',`${exportTabs('text')}<p>Choose accounts to export as otpauth:// setup links, one per line, for compatible authenticator apps.</p><div class="wb-info-strip wb-text-export-note">${icon('key-round')}<span><strong>Unencrypted — contains secret setup keys.</strong><br>Keep this file private. Anyone with it can generate these accounts’ codes.</span></div><div class="wb-import-list">${current.accounts.map(a=>`<label class="wb-choice-row"><input type="checkbox" data-export-id="${a.id}" checked><span><strong>${safe(a.name)}</strong><small><span data-i18n-skip>${safe(a.email)}</span> · ${a.digits} digits · ${a.period}s</small></span></label>`).join('')}</div><button class="wb-primary cursor-interaction" data-save-text>${icon('file-down')}Export selected accounts (.txt)</button><p class="wb-step-note">For phone apps that use QR scanning, use Send to phone.</p>`,'export-text');}
async function chooseImport(){const result=await api.chooseImport();if(!result)return;if(result.encrypted){modal('Restore your backup.',`<p data-i18n-skip>${safe(result.file)}</p><label>Backup password<input id="wb-import-password" type="password" autocomplete="off" placeholder="Enter the password used to export it" maxlength="1024"></label><button class="wb-primary cursor-interaction" data-decrypt-import>${icon('key-round')}Unlock backup</button>`,'restore');}else reviewImport(result);}
function reviewImport(data){pending=data;modal('Bring your accounts home.',`<p><span ${data.fileIsLabel?'':'data-i18n-skip'}>${safe(data.file)}</span> · ${data.accounts.length} account${data.accounts.length===1?'':'s'}</p>${data.migration?`<p class="wb-step-note">${data.migration.scanned} of ${data.migration.total} QR pages scanned.</p>${data.migration.missing.length?'<p class="wb-step-note">Still needed: '+data.migration.missing.join(', ')+'.</p>':''}<button class="wb-secondary cursor-interaction" data-upload-qr>Upload another transfer QR</button>`:''}<div class="wb-step-note">${icon('check-check')}Existing duplicates will be skipped.</div><div class="wb-import-list">${data.accounts.map(a=>`<label class="wb-choice-row"><input type="checkbox" data-import-id="${a.id}" checked><span><strong>${safe(a.name)}</strong><small><span data-i18n-skip>${safe(a.email)}</span> · ${a.digits} digits · ${a.period}s</small></span></label>`).join('')}</div><button class="wb-primary cursor-interaction" data-commit-import ${data.migration?.missing.length?'disabled':''}>${icon('file-check-2')}Import selected accounts</button>`,'review');pending=data;}
function pasteImport(){modal('Import authenticator links',`<p>Paste one otpauth://totp/ link per line.</p><label>Authenticator links<textarea id="wb-import-text" rows="6" autocomplete="off" spellcheck="false" placeholder="otpauth://totp/…"></textarea></label><button class="wb-primary cursor-interaction" data-review-text>${icon('list-checks')}Review accounts</button>`,'paste');}
async function scanQR(){const image=await api.chooseQR();if(!image)return;const img=new Image();img.src=image.dataUrl;await img.decode();if(img.naturalWidth*img.naturalHeight>25000000)throw new Error('The QR image dimensions are too large.');const canvas=document.createElement('canvas');const scale=Math.min(1,1800/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);const found=window.jsQR(pixels.data,pixels.width,pixels.height,{inversionAttempts:'attemptBoth'});canvas.width=canvas.height=0;img.src='';image.dataUrl='';if(!found)throw new Error('No readable QR code found. Try a sharper image or use the setup key.');const result=await api.stageQR({uri:found.data});reviewImport({...result,file:image.file,fileIsLabel:false});}
async function phoneQR(id){const data=await api.showQR({id});modal('Send to your phone.',`<p data-i18n-skip><strong>${safe(data.name)}</strong><br>${safe(data.email)}</p><img class="wb-transfer-qr" src="${data.dataUrl}" alt="Setup QR for the selected authenticator"><div class="wb-info-strip">${icon('smartphone')}<span>In Google Authenticator, tap +, then Scan a QR code. Scan this image to add the same account.</span></div><p class="wb-step-note">This QR contains the account’s secret. Show it only to your own phone.</p><button class="wb-primary cursor-interaction" data-close-modal>Done</button>`,'phone');}
function phonePicker(){if(!current.accounts.length){toast('Add an account before sending it to a phone.');return;}modal('Choose an account.',`<p>Create one setup QR at a time.</p><div class="wb-import-list">${current.accounts.map(a=>`<button class="wb-phone-account cursor-interaction" data-qr="${a.id}"><span class="wb-flow-symbol">${icon('qr-code')}</span><span><strong>${safe(a.name)}</strong><small>${safe(a.email)}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`,'phone-picker');}
async function onboard(){const mode=setupMode,data=await api.googleOnboard({mode,password:q('#wb-vault-password').value,confirm:q('#wb-vault-confirm').value,syncPassword:q('#wb-first-sync-password').value,syncConfirm:q('#wb-first-sync-confirm').value,vaultId:q('#wb-first-cloud-vault')?.value,cloudName:q('#wb-first-cloud-name')?.value,remember:q('#wb-remember-login').checked});state.page='all';setStatus(data);if(mode==='local'){await chooseImport();}else if(data.accounts.length)toast('Your Glacia cloud accounts are restored.');else addModal('qr');}
async function unlock(){const password=q('#wb-vault-password').value;if(!current.hasVault&&password!==q('#wb-vault-confirm').value)throw new Error('The vault passwords do not match.');const data=await api.unlock({password,remember:q('#wb-remember-login').checked});q('#wb-vault-password').value='';setStatus(data);if(!data.accounts.length){state.page='backup';renderPage();toast('Vault ready. Import your file or add an authenticator.');}}
function updateStartupToggle(){const button=q('#wb-start-with-windows');if(!button)return;const startup=current.startup||{};button.setAttribute('aria-checked',String(!!startup.enabled));button.dataset.on=String(!!startup.enabled);button.disabled=busy||!startup.available;q('#wb-startup-label').textContent=startup.enabled?'On':'Off';q('#wb-startup-note').textContent=startup.message||'Open Glacia automatically when you sign in to Windows.';}
async function lockVault(){localSetup=true;setStatus(await api.lock());}
async function signOut(){localSetup=false;setupMode='';cloudChoices=[];setStatus(await api.signOut());}
async function action(button){
if(button.dataset.publicPage){await api.openPublicPage({page:button.dataset.publicPage});return;}
if(!current.locked){const extra=extras.handleAction(button);if(extra){await extra;return;}}
if(button.hasAttribute('data-first-google')){await api.cloudSignIn();setStatus(await api.status());return;}
if(button.hasAttribute('data-local-setup')){localSetup=true;showLock();return;}
if(button.hasAttribute('data-back-to-welcome')){localSetup=false;setupMode='';showLock();return;}
if(button.hasAttribute('data-setup-back')){setupMode='';showLock();return;}
if(button.dataset.setupMode){if(button.dataset.setupMode==='cloud'){cloudChoices=await api.cloudVaults();if(!cloudChoices.length)throw Error('No Glacia cloud backups were found. Restore a local backup or start a new vault.');}setupMode=button.dataset.setupMode;showLock();return;}
if(button.hasAttribute('data-first-disconnect')){await api.cloudDisconnect();localSetup=false;setupMode='';setStatus(await api.status());return;}
if(button.id==='wb-onboard-create'){await onboard();return;}

if(button.hasAttribute('data-cloud-signin')){await api.cloudSignIn();setStatus(await api.status());return;}
if(button.hasAttribute('data-cloud-cancel')){await api.cloudCancelSignIn();setStatus(await api.status());return;}
if(button.hasAttribute('data-cloud-enable')){cloudUnlock();return;}
if(button.hasAttribute('data-cloud-unlock')){const password=q('#wb-sync-password').value,confirm=q('#wb-sync-confirm').value;const data=await api.cloudEnable({password,confirm});if(q('#wb-sync-password'))q('#wb-sync-password').value='';if(q('#wb-sync-confirm'))q('#wb-sync-confirm').value='';closeModal();setStatus(data);toast('Your encrypted vault is synced.');return;}
if(button.hasAttribute('data-cloud-now')){setStatus(await api.cloudSync());toast('Sync complete.');return;}
if(button.hasAttribute('data-cloud-pause')){setStatus(await api.cloudPause());return;}
if(button.hasAttribute('data-cloud-disconnect')){modal('Disconnect Google?', '<p>This stops sync on this computer and removes its saved Google sign-in. Your local accounts and encrypted Google cloud copies stay available.</p><button class="wb-primary cursor-interaction" data-cloud-disconnect-confirm>Disconnect this computer</button>','cloud-disconnect');return;}
if(button.hasAttribute('data-cloud-disconnect-confirm')){const data=await api.cloudDisconnect();closeModal();setStatus(data);return;}

if(button.id==='wb-resume-login'){setStatus(await api.resumeLogin());return;}
if(button.hasAttribute('data-forget-login')){setStatus(await api.forgetLogin());toast('Saved login forgotten.');return;}
if(button.id==='wb-unlock-real'){try{await unlock();}catch(e){q('#wb-unlock-error').textContent=e.message;q('#wb-unlock-error').hidden=false;}return;}
if(button.id==='wb-start-with-windows'){current.startup=await api.setStartup({enabled:!current.startup.enabled});updateStartupToggle();toast(current.startup.enabled?'Glacia will start with Windows.':'Windows startup turned off.');return;}
if(button.id==='wb-theme'){state.dark=!state.dark;theme();await preferences();return;}
if(button.dataset.page){if(current.locked)return;state.page=button.dataset.page;q('#wb-search').value='';renderPage();return;}
if(button.id==='wb-lock-short'){await lockVault();return;}
if(button.id==='wb-lock-button'){await signOut();return;}
if(button.hasAttribute('data-close-modal')){await api.cancelImport();closeModal();return;}
if(button.id==='wb-add'||button.id==='wb-add-nav'||button.hasAttribute('data-open-add')){addModal();return;}
if(button.dataset.addTab){addModal(button.dataset.addTab);return;}
if(button.hasAttribute('data-open-qr')){addModal('qr');return;}
if(button.hasAttribute('data-upload-qr')){await scanQR();return;}
if(button.hasAttribute('data-import-file')){await chooseImport();return;}
if(button.hasAttribute('data-paste-import')){pasteImport();return;}
if(button.hasAttribute('data-review-text')){reviewImport(await api.stageText({text:q('#wb-import-text').value}));return;}
if(button.hasAttribute('data-decrypt-import')){reviewImport(await api.decryptImport({password:q('#wb-import-password').value}));return;}
if(button.hasAttribute('data-commit-import')){const ids=[...root.querySelectorAll('[data-import-id]:checked')].map(el=>el.dataset.importId);const result=await api.commitImport({ids});closeModal();state.page='all';setStatus(result.status);toast(`${result.added} account${result.added===1?'':'s'} imported${result.skipped?`; ${result.skipped} duplicate${result.skipped===1?'':'s'} skipped`:''}.`);return;}
if(button.hasAttribute('data-export')){exportModal();return;}
if(button.dataset.exportFormat){if(button.dataset.exportFormat==='text')textExportModal();else exportModal();return;}
if(button.hasAttribute('data-save-text')){const ids=[...root.querySelectorAll('[data-export-id]:checked')].map(el=>el.dataset.exportId);const result=await api.exportText({ids});if(result){closeModal();toast(`Portable .txt saved: ${result.count} account${result.count===1?'':'s'}.`);}return;}
if(button.hasAttribute('data-save-backup')){const result=await api.export({password:q('#wb-export-password').value,confirm:q('#wb-export-confirm').value});if(result){closeModal();toast(result.statusSaved===false?'Backup saved, but its status could not be recorded.':`Encrypted backup saved: ${result.count} accounts.`);const data=await api.status();current.backup=data.backup;extras.updateBackup();}return;}
if(button.hasAttribute('data-save-manual')||button.hasAttribute('data-save-link')){const record=button.hasAttribute('data-save-link')?{uri:q('#wb-new-uri').value}:{name:q('#wb-new-service').value,email:q('#wb-new-email').value,secret:q('#wb-new-secret').value,folder:q('#wb-new-folder').value,digits:q('#wb-new-digits').value,period:q('#wb-new-period').value,algorithm:q('#wb-new-algorithm').value};const result=await api.add(record);closeModal();state.page='all';setStatus(result);toast('Authenticator added.');return;}
if(button.dataset.delete){await deleteModal(button.dataset.delete);return;}
if(button.hasAttribute('data-delete-confirm')){if(!deleteRequest||performance.now()<deleteRequest.readyAt)return;const data=await api.deleteAccount({id:deleteRequest.id,token:deleteRequest.token});deleteRequest=null;editingNameId=null;nameDraft='';closeModal(false);setStatus(data);(q('[data-delete]')||q('#wb-add')).focus();toast('Authenticator deleted.');return;}
if(button.dataset.reorder){toast('Drag to move this account, or use Alt + Up or Down.');return;}
if(button.dataset.rename){
 const id=button.dataset.rename;
 if(editingNameId!==id){const account=current.accounts.find(a=>a.id===id);if(!account)return;editingNameId=id;nameDraft=account.name;renderAccounts();const input=q('[data-name-input]');input.focus();input.select();return;}
 const input=q('[data-name-input]');input.setCustomValidity(input.value.trim()?'':languageView.translate('Enter an account name.'));if(!input.reportValidity())return;
 current=await api.renameAccount({id,name:input.value});editingNameId=null;nameDraft='';renderAccounts();q('[data-rename="'+id+'"]')?.focus();toast('Name updated.');return;
}
if(button.dataset.favorite){const a=current.accounts.find(a=>a.id===button.dataset.favorite);const result=await api.favorite({id:a.id,favorite:!a.favorite});current=result;renderAccounts();return;}
if(button.dataset.copy){await api.copy({id:button.dataset.copy});toast('Code copied. Clipboard clears after 30 seconds.');return;}
if(button.dataset.qr){await phoneQR(button.dataset.qr);return;}
if(button.hasAttribute('data-phone-picker')){phonePicker();return;}
}
root.addEventListener('click',async e=>{if(Date.now()<suppressReorderClickUntil&&e.target.closest('[data-reorder]'))return;const button=e.target.closest('button');if(!button||button.disabled)return;if(busy&&modalMode==='delete'&&button.hasAttribute('data-close-modal')){closeModal();return;}if(busy&&(button.id==='wb-lock-button'||button.id==='wb-lock-short'||button.hasAttribute('data-cloud-pause')||button.hasAttribute('data-cloud-cancel'))){try{if(button.hasAttribute('data-cloud-cancel')){await api.cloudCancelSignIn();setStatus(await api.status());}else if(button.id==='wb-lock-button')await signOut();else if(button.id==='wb-lock-short')await lockVault();else setStatus(await api.cloudPause());}catch(err){toast(err.message);}return;}if(busy)return;busy=true;button.disabled=true;try{await action(button);}catch(errorObject){error(errorObject.message);}finally{busy=false;if(button.isConnected&&(!current.locked||button.closest('#wb-locked')||button.id==='wb-theme'))button.disabled=(button.id==='wb-start-with-windows'&&!current.startup?.available)||(button.hasAttribute('data-delete-confirm')&&(!deleteRequest||performance.now()<deleteRequest.readyAt));}});
root.addEventListener('input',e=>{if(e.target.matches('[data-name-input]')){nameDraft=e.target.value;e.target.setCustomValidity('');}});
root.addEventListener('change',async e=>{try{const extra=extras.handleChange(e.target);if(extra){await extra;return;}if(e.target.id==='wb-language'){const saved=await api.preferences({language:e.target.value});applyLanguage(saved.language);return;}if(e.target.dataset.accountFolder){const select=e.target;select.disabled=true;try{setStatus(await api.moveAccount({id:select.dataset.accountFolder,folder:select.value}));toast('Folder updated.');}catch(error){select.value=current.accounts.find(a=>a.id===select.dataset.accountFolder)?.folder||'personal';throw error;}finally{if(select.isConnected)select.disabled=false;}return;}if(e.target.id==='wb-appearance'){state.dark=e.target.value==='dark';theme();await preferences();}if(e.target.id==='wb-layout'){state.layout=e.target.value;theme();await preferences();}if(e.target.id==='wb-auto-lock'){state.autoLock=Number(e.target.value);await preferences();}}catch(e){error(e.message);}});
function markAccountDrop(e){
 root.querySelectorAll('.is-drop-before,.is-drop-after').forEach(el=>el.classList.remove('is-drop-before','is-drop-after'));dropAccountId=null;
 const card=document.elementFromPoint(e.clientX,e.clientY)?.closest('.wb-account');if(!dragAccountId||current.locked||busy||!card||card.dataset.accountId===dragAccountId)return null;
 const rect=card.getBoundingClientRect(),vertical=getComputedStyle(q('#wb-account-grid')).gridTemplateColumns.split(' ').length===1;
 dropAccountId=card.dataset.accountId;dropAfter=vertical?e.clientY>rect.top+rect.height/2:e.clientX>rect.left+rect.width/2;
 q('#wb-account-grid').classList.toggle('wb-reorder-vertical',vertical);card.classList.add(dropAfter?'is-drop-after':'is-drop-before');return card;
}
root.addEventListener('pointerdown',e=>{
 const zone=e.target.closest('[data-reorder],.wb-service-mark,.wb-service-text'),card=zone?.closest('.wb-account');
 if(!card||e.button!==0||busy||current.locked||editingNameId||e.target.closest('input,select,textarea,button:not([data-reorder])'))return;
 e.preventDefault();zone.closest('[data-reorder]')?.focus();pointerDrag={pointerId:e.pointerId,id:card.dataset.accountId,startX:e.clientX,startY:e.clientY,clientX:e.clientX,clientY:e.clientY,active:false};root.setPointerCapture(e.pointerId);
});
function scrollAccountDrag(){
 if(!pointerDrag?.active)return;const y=pointerDrag.clientY,dy=y<90?-10:y>window.innerHeight-50?10:0;
 if(dy){const main=q('.wb-main');if(getComputedStyle(main).overflowY==='auto')main.scrollBy(0,dy);else window.scrollBy(0,dy);markAccountDrop(pointerDrag);}dragScrollFrame=requestAnimationFrame(scrollAccountDrag);
}
root.addEventListener('pointermove',e=>{
 if(!pointerDrag||pointerDrag.pointerId!==e.pointerId)return;pointerDrag.clientX=e.clientX;pointerDrag.clientY=e.clientY;
 if(!pointerDrag.active&&Math.hypot(e.clientX-pointerDrag.startX,e.clientY-pointerDrag.startY)<6)return;
 e.preventDefault();if(!pointerDrag.active){pointerDrag.active=true;dragAccountId=pointerDrag.id;q('[data-account-id="'+dragAccountId+'"]')?.classList.add('is-dragging');const preview=document.createElement('div');preview.className='wb-drag-preview';preview.textContent=current.accounts.find(a=>a.id===dragAccountId)?.name||'Moving account';root.append(preview);dragScrollFrame=requestAnimationFrame(scrollAccountDrag);}
 const preview=q('.wb-drag-preview');preview.style.left=Math.min(e.clientX+14,window.innerWidth-preview.offsetWidth-8)+'px';preview.style.top=Math.min(e.clientY+14,window.innerHeight-preview.offsetHeight-8)+'px';markAccountDrop(e);
});
root.addEventListener('pointerup',e=>{
 if(!pointerDrag||pointerDrag.pointerId!==e.pointerId)return;const moved=pointerDrag.active;if(moved)markAccountDrop(e);const id=dragAccountId,targetId=dropAccountId,after=dropAfter;clearAccountDrag();
 if(moved){e.preventDefault();suppressReorderClickUntil=Date.now()+250;if(targetId)placeAccount(id,targetId,after);}
});
root.addEventListener('pointercancel',clearAccountDrag);
root.addEventListener('lostpointercapture',()=>{if(pointerDrag)clearAccountDrag();});
window.addEventListener('blur',clearAccountDrag);
root.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&pointerDrag){e.preventDefault();clearAccountDrag();return;}
 const handle=e.target.closest('[data-reorder]');if(!handle||!e.altKey||!['ArrowUp','ArrowDown'].includes(e.key)||busy||current.locked)return;
 e.preventDefault();const shown=filtered(),index=shown.findIndex(a=>a.id===handle.dataset.reorder),after=e.key==='ArrowDown',target=shown[index+(after?1:-1)];
 if(target)placeAccount(handle.dataset.reorder,target.id,after);
});
q('#wb-search').addEventListener('input',renderAccounts);
root.addEventListener('pointerdown',()=>{if(Date.now()-focusTouch>10000){focusTouch=Date.now();api.touch().catch(()=>{});}});
root.addEventListener('keydown',e=>{if(e.target.closest('.wb-window-controls'))return;if(e.target.matches('[data-name-input]')){if(e.key==='Enter'){e.preventDefault();q('[data-rename="'+editingNameId+'"]')?.click();return;}if(e.key==='Escape'){e.preventDefault();const id=editingNameId;editingNameId=null;nameDraft='';renderAccounts();q('[data-rename="'+id+'"]')?.focus();return;}}if(Date.now()-focusTouch>10000){focusTouch=Date.now();api.touch().catch(()=>{});}if(current.locked&&e.key==='Enter'&&!e.target.closest('[data-public-page]')){e.preventDefault();(q('#wb-onboard-create')||q('#wb-unlock-real')||q('[data-first-google]'))?.click();return;}if(!q('#wb-modal-shade').hidden){if(e.key==='Escape'){if(modalMode==='cloud-unlock')api.cloudPause().catch(()=>{});api.cancelImport().catch(()=>{});closeModal();return;}if(e.key==='Tab'){const nodes=[...q('.wb-modal').querySelectorAll('button,input,select,textarea,summary')].filter(el=>el.getClientRects().length&&!el.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
api.onLocked(()=>{clearAccountDrag();editingNameId=null;nameDraft='';current={...current,locked:true,accounts:[]};closeModal(false);showLock();});
api.onCloudChanged?.(()=>api.status().then(data=>{const changed=JSON.stringify(current.cloud)!==JSON.stringify(data.cloud);current.cloud=data.cloud;extras.updateSync();if(changed&&current.locked&&!busy)showLock();else if(changed&&state.page==='cloud'&&!current.locked)renderCloud();}).catch(()=>{}));
async function refresh(){
 if(refreshing||busy)return;refreshing=true;
 try{
  const data=await api.status();applyLanguage(data.preferences.language);
  if(data.hasVault!==current.hasVault||data.locked!==current.locked){setStatus(data);return;}
  const cloudChanged=JSON.stringify(current.cloud)!==JSON.stringify(data.cloud),foldersChanged=JSON.stringify(current.folders)!==JSON.stringify(data.folders);
  const metadata=list=>JSON.stringify(list.map(a=>[a.id,a.name,a.issuer,a.email,a.folder,a.favorite]));
  const listChanged=metadata(current.accounts)!==metadata(data.accounts),startupChanged=JSON.stringify(current.startup)!==JSON.stringify(data.startup);
  current=data;extras.updateSync();extras.updateBackup();
  if(data.locked){if(cloudChanged)showLock();return;}
  if(startupChanged)updateStartupToggle();
  if(listChanged||foldersChanged){clearAccountDrag();if(deleteRequest&&!data.accounts.some(a=>a.id===deleteRequest.id))closeModal(false);renderPage();}
  else if(cloudChanged&&state.page==='cloud')renderCloud();
  const seconds=30-Math.floor(Date.now()/1000)%30;q('#wb-countdown').textContent=seconds+'s';
  for(const a of data.accounts){const code=q(`[data-code="${a.id}"]`),track=q(`[data-track="${a.id}"]`),remaining=q(`[data-remaining="${a.id}"]`);if(code){code.textContent=format(a.code);code.classList.toggle('is-expiring',a.remaining<=5);}if(track)track.style.width=(a.remaining/a.period*100)+'%';if(remaining)remaining.textContent=`${a.remaining}s · ${a.period} SEC`;}
 }catch(e){toast(e.message);}finally{refreshing=false;}
}
api.onNavigate?.(page=>{if(!['all','settings'].includes(page))return;state.page=page;if(!current.locked)renderPage();});
api.status().then(setStatus).catch(e=>toast(e.message));setInterval(refresh,1000);
})();

